#!/usr/bin/env python3
"""Writes the *.Designer.cs class for a .resx, in the layout Visual Studio's PublicResXFileCodeGenerator produces."""
import pathlib
import sys
import xml.etree.ElementTree as ET

ROOT = pathlib.Path(__file__).resolve().parent.parent

TEMPLATE_HEAD = '''//------------------------------------------------------------------------------
// <auto-generated>
//     This code was generated by a tool.
//
//     Changes to this file may cause incorrect behavior and will be lost if
//     the code is regenerated.
// </auto-generated>
//------------------------------------------------------------------------------

namespace {namespace} {{
    using System;


    /// <summary>
    ///   A strongly-typed resource class, for looking up localized strings, etc.
    /// </summary>
    // This class was auto-generated by the StronglyTypedResourceBuilder
    // class via a tool like ResGen or Visual Studio.
    // To add or remove a member, edit your .ResX file then rerun ResGen
    // with the /str option, or rebuild your VS project.
    [global::System.CodeDom.Compiler.GeneratedCodeAttribute("System.Resources.Tools.StronglyTypedResourceBuilder", "17.0.0.0")]
    [global::System.Diagnostics.DebuggerNonUserCodeAttribute()]
    [global::System.Runtime.CompilerServices.CompilerGeneratedAttribute()]
    public class {cls} {{

        private static global::System.Resources.ResourceManager resourceMan;

        private static global::System.Globalization.CultureInfo resourceCulture;

        [global::System.Diagnostics.CodeAnalysis.SuppressMessageAttribute("Microsoft.Performance", "CA1811:AvoidUncalledPrivateCode")]
        internal {cls}() {{
        }}

        /// <summary>
        ///   Returns the cached ResourceManager instance used by this class.
        /// </summary>
        [global::System.ComponentModel.EditorBrowsableAttribute(global::System.ComponentModel.EditorBrowsableState.Advanced)]
        public static global::System.Resources.ResourceManager ResourceManager {{
            get {{
                if (object.ReferenceEquals(resourceMan, null)) {{
                    global::System.Resources.ResourceManager temp = new global::System.Resources.ResourceManager("{basename}", typeof({cls}).Assembly);
                    resourceMan = temp;
                }}
                return resourceMan;
            }}
        }}

        /// <summary>
        ///   Overrides the current thread's CurrentUICulture property for all
        ///   resource lookups using this strongly typed resource class.
        /// </summary>
        [global::System.ComponentModel.EditorBrowsableAttribute(global::System.ComponentModel.EditorBrowsableState.Advanced)]
        public static global::System.Globalization.CultureInfo Culture {{
            get {{
                return resourceCulture;
            }}
            set {{
                resourceCulture = value;
            }}
        }}
'''

PROPERTY = '''
        /// <summary>
        ///   Looks up a localized string similar to {summary}.
        /// </summary>
        public static string {key} {{
            get {{
                return ResourceManager.GetString("{key}", resourceCulture);
            }}
        }}
'''


def summary(value):
    text = value.replace('\r', '').split('\n')[0]
    if len(text) > 80 or '\n' in value:
        text = text[:80].rstrip() + ' [rest of string was truncated]";'
    return text.replace('*/', '* /')


def generate(resx, namespace, cls, basename, out):
    tree = ET.parse(ROOT / resx)
    keys = [(d.get('name'), d.findtext('value') or '') for d in tree.getroot().findall('data')]
    if len(set(k for k, _ in keys)) != len(keys):
        sys.exit(f'{resx}: duplicate keys')
    parts = [TEMPLATE_HEAD.format(namespace=namespace, cls=cls, basename=basename)]
    for key, value in sorted(keys):
        parts.append(PROPERTY.format(key=key, summary=summary(value)))
    parts.append('    }\n}\n')
    (ROOT / out).write_text(''.join(parts), encoding='utf-8-sig')
    print(f'{out}: {len(keys)} properties')


generate('src/DesktopIconGrid/Resources/Strings.resx', 'DesktopIconGrid.Resources', 'Strings',
         'DesktopIconGrid.Resources.Strings', 'src/DesktopIconGrid/Resources/Strings.Designer.cs')
generate('src/DesktopIconGrid.Core/Resources/CoreStrings.resx', 'DesktopIconGrid.Core.Resources', 'CoreStrings',
         'DesktopIconGrid.Core.Resources.CoreStrings', 'src/DesktopIconGrid.Core/Resources/CoreStrings.Designer.cs')
